fn load() -> Vec<P4Fixture> {
    let dir: PathBuf = fixture_dir().join("phase4");
    let mut paths: Vec<PathBuf> = std::fs::read_dir(&dir)
        .expect("phase-4 fixture directory exists")
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|e| e == "json"))
        .collect();
    paths.sort();
    assert!(paths.len() >= 13, "phase-4 fixtures are missing");
    paths
        .iter()
        .map(|p| {
            serde_json::from_str(&std::fs::read_to_string(p).unwrap())
                .unwrap_or_else(|e| panic!("failed to parse {}: {e}", p.display()))
        })
        .collect()
}

/// The model of one fixture entry (BoTorch's `SingleTaskGP(train_X, train_Y, ...)`).
fn build_member(f: &P4Model) -> BatchedMultiOutputGP {
    let c = &f.config;
    let nb: usize = c.batch_shape.iter().product();
    let x: Vec<Matrix> = f.train_x.iter().map(|b| matrix(b)).collect();
    let y: Vec<Matrix> = f.train_y.iter().map(|b| matrix(b)).collect();
    let mut options = BatchedMultiOutputGPOptions {
        train_yvar: f
            .train_yvar
            .as_ref()
            .map(|v| v.iter().map(|b| matrix(b)).collect()),
        ..Default::default()
    };
    match c.covar.as_str() {
        "rbf" => {}
        "matern" => options.kernel = KernelKind::Matern52,
        "matern_gamma" => options.covar_module = Some(get_matern_kernel_with_gamma_prior(c.d)),
        other => panic!("unknown covar {other}"),
    }
    if c.likelihood == "gamma" {
        options.likelihood = Some(get_gaussian_likelihood_with_gamma_prior());
    }
    options.input_transform = match c.normalize.as_deref() {
        None => None,
        Some("shared") => Some(BatchedInputTransform::Shared(Normalize::new(c.d))),
        Some("per_batch") => Some(BatchedInputTransform::PerBatch(vec![
            Normalize::new(c.d);
            nb
        ])),
        Some("explicit") => Some(BatchedInputTransform::Shared(
            Normalize::with_bounds(&matrix(c.bounds.as_ref().unwrap())).unwrap(),
        )),
        Some(other) => panic!("unknown normalize {other}"),
    };
    if c.outcome == "none" {
        options.outcome_transform = OutcomeTransformChoice::None;
    }
    let model = BatchedMultiOutputGP::new(x, y, c.batch_shape.clone(), options).unwrap();
    assert_eq!(model.batch_size(), nb.max(1));
    assert_eq!(model.num_outputs(), c.m);
    model
}

/// A fixture's model: a (batched, multi-output) `SingleTaskGP` or a `ModelListGP`.
#[allow(clippy::large_enum_variant)]
enum TestModel {
    Single(BatchedMultiOutputGP),
    List(ModelListGP),
}

impl TestModel {
    fn new(f: &P4Fixture, raw: bool) -> Self {
        let mut members: Vec<BatchedMultiOutputGP> = f.models.iter().map(build_member).collect();
        if raw {
            for (m, fm) in members.iter_mut().zip(&f.models) {
                m.set_raw_parameters(&fm.raw_params).unwrap();
            }
        }
        match f.kind.as_str() {
            "single_task" => {
                assert_eq!(members.len(), 1);
                TestModel::Single(members.pop().unwrap())
            }
            "model_list" => TestModel::List(ModelListGP::new(members).unwrap()),
            other => panic!("unknown kind {other}"),
        }
    }

    fn batch_size(&self) -> usize {
        match self {
            TestModel::Single(m) => m.batch_size(),
            TestModel::List(l) => l.models()[0].batch_size(),
        }
    }

    fn num_outputs(&self) -> usize {
        match self {
            TestModel::Single(m) => m.num_outputs(),
            TestModel::List(l) => l.num_outputs(),
        }
    }

    fn posterior_at(&self, b: usize, x: &Matrix, noise: bool) -> Posterior {
        match self {
            TestModel::Single(m) => m.posterior_at(b, x, noise).unwrap(),
            TestModel::List(l) => l.posterior_at(b, x, noise).unwrap(),
        }
    }

    fn point_posteriors_at(
        &self,
        b: usize,
        x: &Matrix,
        noise: bool,
    ) -> botorch_core::PointPosteriors {
        match self {
            TestModel::Single(m) => m.point_posteriors_at(b, x, noise).unwrap(),
            TestModel::List(l) => l.point_posteriors_at(b, x, noise).unwrap(),
        }
    }

    fn arc(self) -> Arc<dyn Model> {
        match self {
            TestModel::Single(m) => Arc::new(m),
            TestModel::List(l) => Arc::new(l),
        }
    }
}

/// Compares the posteriors of the batch elements `b` (one per input) with a
/// BoTorch posterior of shape `batch × q × m` (`covariance` `batch × qm × qm`).
fn check_posteriors(r: &mut Report, name: &str, label: &str, posts: &[Posterior], e: &P4Posterior) {
    let q = posts[0].num_points();
    let m = posts[0].num_outputs();
    let qm = q * m;
    assert_eq!(
        e.mean_shape[e.mean_shape.len() - 2..],
        [q, m],
        "{name}: {label}"
    );
    assert_eq!(e.covariance_shape[e.covariance_shape.len() - 2..], [qm, qm]);
    let (mut mean, mut var, mut cov) = (Vec::new(), Vec::new(), Vec::new());
    for p in posts {
        let mm = p.mean_matrix();
        let vm = p.variance_matrix();
        for i in 0..q {
            for t in 0..m {
                mean.push(mm[(i, t)]);
                var.push(vm[(i, t)]);
            }
        }
        cov.extend(matrix_rows(&p.covariance));
    }
    r.check_slices(name, &format!("{label} mean"), &mean, &e.mean, RTOL);
    r.check_slices(name, &format!("{label} variance"), &var, &e.variance, RTOL);
    r.check_slices(
        name,
        &format!("{label} covariance"),
        &cov,
        &e.covariance,
        RTOL,
    );
}

#[test]
fn parity_parameters_and_mll() {
    let mut r = Report::default();
    for f in load() {
        for (i, fm) in f.models.iter().enumerate() {
            let mut model = build_member(fm);
            let label = format!("model {i}");
            assert_eq!(model.parameter_names(), fm.param_names, "{}: names", f.name);
            assert_eq!(
                model.parameter_shapes(),
                fm.param_shapes,
                "{}: shapes",
                f.name
            );
            r.check_slices(
                &f.name,
                &format!("{label} default raw params"),
                model.raw_parameters().as_slice(),
                &fm.default_raw_params,
                0.0,
            );
            let values = model.mll_values().unwrap();
            r.check_slices(
                &f.name,
                &format!("{label} default mll values"),
                &values,
                &fm.default_mll.values,
                RTOL,
            );
            let (v, g) = model.mll_values_and_grad(&fm.default_raw_params).unwrap();
            assert_eq!(v, values);
            r.check_slices_atol(
                &f.name,
                &format!("{label} default mll grad"),
                g.as_slice(),
                &fm.default_mll.grad,
                RTOL,
                GRAD_ATOL,
            );
            model.set_raw_parameters(&fm.raw_params).unwrap();
            assert_eq!(model.raw_parameters().as_slice(), fm.raw_params.as_slice());
            r.check_slices(
                &f.name,
                &format!("{label} mll values"),
                &model.mll_values().unwrap(),
                &fm.mll.values,
                RTOL,
            );
            let (_, g) = model.mll_values_and_grad(&fm.raw_params).unwrap();
            r.check_slices_atol(
                &f.name,
                &format!("{label} mll grad"),
                g.as_slice(),
                &fm.mll.grad,
                RTOL,
                GRAD_ATOL,
            );
        }
    }
    r.finish("multi-output parameters and MLL");
}

#[test]
fn parity_posteriors() {
    let mut r = Report::default();
    for f in load() {
        let model = TestModel::new(&f, true);
        let xt = matrix(&f.test_x);
        let nb = model.batch_size();
        for (noise, e, label) in [
            (false, &f.posterior, "joint posterior"),
            (true, &f.posterior_noisy, "joint posterior (obs noise)"),
        ] {
            let posts: Vec<Posterior> =
                (0..nb).map(|b| model.posterior_at(b, &xt, noise)).collect();
            check_posteriors(&mut r, &f.name, label, &posts, e);
            // Point posteriors (q = 1 each) equal the joint marginals.
            let (mut mean, mut var) = (Vec::new(), Vec::new());
            for b in 0..nb {
                let pp = model.point_posteriors_at(b, &xt, noise);
                for i in 0..xt.nrows() {
                    for t in 0..model.num_outputs() {
                        mean.push(pp.mean[(i, t)]);
                        var.push(pp.variance(i, t).max(botorch_core::posterior::MIN_VARIANCE));
                    }
                }
            }
            r.check_slices(
                &f.name,
                &format!("{label} point means"),
                &mean,
                &e.mean,
                RTOL,
            );
            r.check_slices(
                &f.name,
                &format!("{label} point variances"),
                &var,
                &e.variance,
                RTOL,
            );
        }
        if let (Some(xb), Some(e)) = (&f.batched_x, &f.posterior_batched) {
            let posts: Vec<Posterior> = (0..nb)
                .map(|b| model.posterior_at(b, &matrix(&xb[b]), false))
                .collect();
            check_posteriors(&mut r, &f.name, "batched X", &posts, e);
        }
        if let (Some(xe), Some(e)) = (&f.extra_batch_x, &f.posterior_extra_batch) {
            // X of shape `2 x 1 x q x d` broadcast against the model batch.
            let mut posts = Vec::new();
            for x in xe {
                for b in 0..nb {
                    posts.push(model.posterior_at(b, &matrix(x), false));
                }
            }
            assert_eq!(e.mean_shape[..2], [xe.len(), nb]);
            check_posteriors(&mut r, &f.name, "extra batch dims", &posts, e);
        }
    }
    r.finish("multi-output posteriors");
}

#[test]
fn parity_posterior_gradients() {
    let mut r = Report::default();
    for f in load() {
        let Some(pg) = &f.posterior_grad else {
            continue;
        };
        let model = TestModel::new(&f, true).arc();
        let x = matrix(&pg.x);
        let (q, d) = x.shape();
        let m = model.num_outputs();
        let g = model.joint_posterior_with_grad(&x).unwrap();
        assert_eq!((g.num_outputs, g.dmean.len()), (m, q * d));
        let (mut dm_a, mut dm_e, mut dc_a, mut dc_e) =
            (Vec::new(), Vec::new(), Vec::new(), Vec::new());
        // BoTorch: dmean[p][t][p'][k] (mean q x m), dcov[a][b][p'][k].
        for p in 0..q {
            for t in 0..m {
                for pp in 0..q {
                    for k in 0..d {
                        dm_a.push(g.dmean[pp * d + k][t * q + p]);
                        dm_e.push(pg.dmean[((p * m + t) * q + pp) * d + k]);
                    }
                }
            }
        }
        let n = q * m;
        for a in 0..n {
            for b in 0..n {
                for pp in 0..q {
                    for k in 0..d {
                        dc_a.push(g.dcov[pp * d + k][(a, b)]);
                        dc_e.push(pg.dcov[((a * n + b) * q + pp) * d + k]);
                    }
                }
            }
        }
        r.check_slices_atol(&f.name, "joint dmean/dx", &dm_a, &dm_e, RTOL, GRAD_ATOL);
        r.check_slices_atol(&f.name, "joint dcov/dx", &dc_a, &dc_e, RTOL, GRAD_ATOL);
        // Reverse mode equals the contraction of the forward-mode derivatives.
        let ma = Vector::from_fn(n, |i, _| 0.4 - 0.15 * i as f64);
        let ca = Matrix::from_fn(n, n, |i, j| ((i * 5 + j * 3) % 7) as f64 / 7.0 - 0.3);
        let vjp = model.joint_posterior_vjp(&x, 0..q, &ma, &ca).unwrap();
        let mut expected = Vec::new();
        for p in 0..q {
            for k in 0..d {
                let j = p * d + k;
                expected.push(ma.dot(&g.dmean[j]) + ca.component_mul(&g.dcov[j]).sum());
            }
        }
        r.check_slices(
            &f.name,
            "VJP vs forward mode",
            &matrix_rows(&vjp),
            &expected,
            1e-12,
        );
        // q = 1 point posteriors with gradients equal the joint ones.
        let pg1 = model.point_posterior_with_grad(&pg.x[0]).unwrap();
        let g1 = model
            .joint_posterior_with_grad(&matrix(std::slice::from_ref(&pg.x[0])))
            .unwrap();
        r.check_slices(
            &f.name,
            "point mean",
            pg1.mean.as_slice(),
            g1.mean.as_slice(),
            1e-13,
        );
        let dm1: Vec<f64> = pg1.dmean.iter().flat_map(|v| v.iter().copied()).collect();
        let dm2: Vec<f64> = g1.dmean.iter().flat_map(|v| v.iter().copied()).collect();
        r.check_slices(&f.name, "point dmean", &dm1, &dm2, 1e-12);
    }
    r.finish("multi-output posterior gradients");
}

#[test]
fn parity_fit() {
    let mut r = Report::default();
    println!(
        "{:44} {:>7} {:>14} {:>14} {:>10} {:>6} {:>6}",
        "fixture", "element", "botorch loss", "rust loss", "excess", "it(bt)", "it(rs)"
    );
    for f in load() {
        // The Rust MLL reproduces BoTorch's losses at BoTorch's optimum.
        for (i, (fm, fit)) in f.models.iter().zip(&f.fit).enumerate() {
            let mut m = build_member(fm);
            m.set_raw_parameters(&fit.raw_params).unwrap();
            let losses: Vec<f64> = m.mll_values().unwrap().iter().map(|v| -v).collect();
            r.check_slices(
                &f.name,
                &format!("model {i} losses at BoTorch optimum"),
                &losses,
                &fit.losses,
                RTOL,
            );
        }
        let mut model = TestModel::new(&f, false);
        let results = match &mut model {
            TestModel::Single(m) => vec![fit_gpytorch_mll(m, FitOptions::default()).unwrap()],
            TestModel::List(l) => fit_gpytorch_mll(l, FitOptions::default()).unwrap(),
        };
        let members: Vec<BatchedMultiOutputGP> = match &model {
            TestModel::Single(m) => vec![m.clone()],
            TestModel::List(l) => l.models().iter().map(|m| (**m).clone()).collect(),
        };
        for (i, ((res, fit), member)) in results.iter().zip(&f.fit).zip(&members).enumerate() {
            assert_ne!(res.status, FitStatus::Failure);
            assert_eq!(res.results.len(), fit.losses.len());
            let losses: Vec<f64> = member.mll_values().unwrap().iter().map(|v| -v).collect();
            for (e, ((er, loss), bt_loss)) in
                res.results.iter().zip(&losses).zip(&fit.losses).enumerate()
            {
                assert!((er.loss - loss).abs() <= 1e-12 * (1.0 + loss.abs()));
                let it_bt = match &fit.result.elements {
                    Some(els) => {
                        assert!((els[e].fun - bt_loss).abs() <= 1e-12 * (1.0 + bt_loss.abs()));
                        els[e].nit
                    }
                    None => fit.result.step,
                };
                let excess = er.loss - bt_loss;
                println!(
                    "{:44} {:>7} {:>14.10} {:>14.10} {:>10.2e} {:>6} {:>6}",
                    f.name,
                    format!("{i}.{e}"),
                    bt_loss,
                    er.loss,
                    excess,
                    it_bt,
                    er.iterations
                );
                r.check(
                    &f.name,
                    &format!("model {i}.{e} fit loss excess"),
                    excess.max(0.0),
                    1e-6,
                );
            }
            // BoTorch's summary: fval is the sum of the element losses.
            let bt_sum: f64 = fit.losses.iter().sum();
            assert!((fit.result.fval - bt_sum).abs() <= 1e-10 * (1.0 + bt_sum.abs()));
            assert_eq!(fit.result.status, "SUCCESS");
            if res.results.len() > 1 {
                assert!(
                    res.message.starts_with("Batched L-BFGS-B: "),
                    "{}",
                    res.message
                );
            }
        }
    }
    r.finish("batched independent fits");
}

/// Relative error of a scalar (absolute if the reference is zero).
fn scalar_rel(a: f64, e: f64) -> f64 {
    if e == 0.0 {
        a.abs()
    } else {
        (a - e).abs() / e.abs()
    }
}

/// Error of a log-space scalar: absolute for |e| < 1, relative otherwise.
fn log_err(a: f64, e: f64) -> f64 {
    (a - e).abs() / e.abs().max(1.0)
}

fn sampler_from(base: &[Vec<f64>]) -> Option<Arc<SobolQMCNormalSampler>> {
    Some(Arc::new(
        SobolQMCNormalSampler::from_base_samples(matrix(base), Some(0)).unwrap(),
    ))
}

fn analytic_acqf(model: Arc<dyn Model>, c: &P4Analytic) -> Box<dyn AcquisitionFunction> {
    let (b, mx) = (c.best_f, c.maximize);
    match c.acqf.as_str() {
        "ExpectedImprovement" => Box::new(ExpectedImprovement::new(model, b.unwrap(), mx).unwrap()),
        "LogExpectedImprovement" => {
            Box::new(LogExpectedImprovement::new(model, b.unwrap(), mx).unwrap())
        }
        "ProbabilityOfImprovement" => {
            Box::new(ProbabilityOfImprovement::new(model, b.unwrap(), mx).unwrap())
        }
        "LogProbabilityOfImprovement" => {
            Box::new(LogProbabilityOfImprovement::new(model, b.unwrap(), mx).unwrap())
        }
        "UpperConfidenceBound" => {
            Box::new(UpperConfidenceBound::new(model, c.beta.unwrap(), mx).unwrap())
        }
        "PosteriorMean" => Box::new(PosteriorMean::new(model, mx).unwrap()),
        "PosteriorStandardDeviation" => {
            Box::new(PosteriorStandardDeviation::new(model, mx).unwrap())
        }
        other => panic!("unknown acquisition function {other}"),
    }
}

fn mc_acqf(
    model: Arc<dyn Model>,
    c: &P4McResult,
    base: &[Vec<f64>],
    pending: Option<Matrix>,
) -> Box<dyn AcquisitionFunction> {
    let opts = McAcquisitionOptions {
        sampler: sampler_from(base),
        x_pending: pending.clone(),
        ..Default::default()
    };
    match c.acqf.as_str() {
        "qExpectedImprovement" => {
            Box::new(QExpectedImprovement::new(model, c.best_f.unwrap(), opts).unwrap())
        }
        "qLogExpectedImprovement" => Box::new(
            QLogExpectedImprovement::new(
                model,
                c.best_f.unwrap(),
                QLogExpectedImprovementOptions {
                    sampler: sampler_from(base),
                    x_pending: pending,
                    ..Default::default()
                },
            )
            .unwrap(),
        ),
        "qProbabilityOfImprovement" => Box::new(
            QProbabilityOfImprovement::new(model, c.best_f.unwrap(), c.tau.unwrap(), opts).unwrap(),
        ),
        "qUpperConfidenceBound" => {
            Box::new(QUpperConfidenceBound::new(model, c.beta.unwrap(), opts).unwrap())
        }
        "qSimpleRegret" => Box::new(QSimpleRegret::new(model, opts).unwrap()),
        other => panic!("unknown acquisition function {other}"),
    }
}

/// The model of an unbatched fixture with BoTorch's explicit hyperparameters
/// and the scalarized model of its posterior transform.
fn acqf_models(f: &P4Fixture, a: &P4Acqf) -> (Arc<dyn Model>, Arc<dyn Model>) {
    let model = TestModel::new(f, true).arc();
    let t =
        ScalarizedPosteriorTransform::new(Vector::from_vec(a.weights.clone()), a.offset).unwrap();
    let s = ScalarizedModel::wrap(model.clone(), Some(t)).unwrap();
    assert_eq!(s.num_outputs(), 1);
    (model, s)
}

#[test]
fn parity_scalarized_acquisition() {
    let mut r = Report::default();
    for f in load() {
        let Some(a) = &f.acqf else {
            continue;
        };
        let (_, scalarized) = acqf_models(&f, a);
        let xs: Vec<Matrix> = f
            .test_x
            .iter()
            .map(|x| matrix(std::slice::from_ref(x)))
            .collect();
        for c in &a.analytic {
            let acqf = analytic_acqf(scalarized.clone(), c);
            let label = format!(
                "{} b={:.3e} beta={:?} max={}",
                c.acqf,
                c.best_f.unwrap_or(f64::NAN),
                c.beta,
                c.maximize
            );
            let many = acqf.forward_many(&xs).unwrap();
            let (mut verr, mut grads) = (0.0f64, Vec::new());
            for (i, x) in xs.iter().enumerate() {
                let (v, g) = acqf.forward_with_grad(x).unwrap();
                assert_eq!(many[i], acqf.forward(x).unwrap());
                assert!(
                    scalar_rel(many[i], v)
                        <= 1e-14 * if acqf.is_log() { v.abs().max(1.0) } else { 1.0 }
                );
                let e = c.values[i];
                verr = verr.max(if acqf.is_log() {
                    log_err(v, e)
                } else {
                    scalar_rel(v, e)
                });
                grads.push(rel_err(g.as_slice(), &c.grads[i]));
            }
            r.check(&f.name, &format!("{label} value"), verr, RTOL);
            r.check(
                &f.name,
                &format!("{label} grad"),
                grads.iter().copied().fold(0.0, f64::max),
                RTOL,
            );
        }
        for case in &a.mc {
            let x = matrix(&case.x);
            assert_eq!(x.nrows(), case.q);
            let pending = case.x_pending.as_ref().map(|p| matrix(p));
            for c in &case.results {
                let acqf = mc_acqf(scalarized.clone(), c, &case.base_samples, pending.clone());
                let (v, g) = acqf.forward_with_grad(&x).unwrap();
                let label = format!("{} q={} pending={}", c.acqf, case.q, pending.is_some());
                let verr = if acqf.is_log() {
                    log_err(v, c.value)
                } else {
                    scalar_rel(v, c.value)
                };
                r.check(&f.name, &format!("{label} value"), verr, RTOL);
                r.check_slices_atol(
                    &f.name,
                    &format!("{label} grad"),
                    &matrix_rows(&g),
                    &flatten(&c.grad),
                    RTOL,
                    GRAD_ATOL,
                );
            }
        }
        let baseline = matrix(&f.models[0].train_x[0]);
        for c in &a.nei {
            let pending = c.x_pending.as_ref().map(|p| matrix(p));
            let acqf = QLogNoisyExpectedImprovement::new(
                scalarized.clone(),
                &baseline,
                QLogNoisyExpectedImprovementOptions {
                    cache_root: false,
                    sampler: sampler_from(&c.base_samples),
                    x_pending: pending.clone(),
                    prune_baseline: false,
                    incremental: c.incremental,
                    ..Default::default()
                },
            )
            .unwrap();
            let x = matrix(&c.x);
            let (v, g) = acqf.forward_with_grad(&x).unwrap();
            let label = format!(
                "qLogNEI q={} pending={} inc={}",
                c.q,
                pending.is_some(),
                c.incremental
            );
            r.check(
                &f.name,
                &format!("{label} value"),
                log_err(v, c.value),
                RTOL,
            );
            r.check_slices_atol(
                &f.name,
                &format!("{label} grad"),
                &matrix_rows(&g),
                &flatten(&c.grad),
                RTOL,
                GRAD_ATOL,
            );
        }
        let z = matrix(&a.prune.base_samples);
        let options = PruneOptions {
            num_samples: z.nrows(),
            base_samples: Some(z),
            ..Default::default()
        };
        let idx = prune_inferior_points_indices(scalarized.as_ref(), &matrix(&a.prune.x), &options)
            .unwrap();
        assert_eq!(idx, a.prune.indices, "{}: pruned indices", f.name);
    }
    r.finish("acquisition functions with ScalarizedPosteriorTransform");
}

#[test]
fn parity_constrained_expected_improvement() {
    let mut r = Report::default();
    let mut n_cases = 0;
    for f in load() {
        let Some(a) = &f.acqf else {
            continue;
        };
        let (model, _) = acqf_models(&f, a);
        let xs: Vec<Matrix> = f
            .test_x
            .iter()
            .map(|x| matrix(std::slice::from_ref(x)))
            .collect();
        for c in &a.constrained {
            n_cases += 1;
            let acqf: Box<dyn AcquisitionFunction> = match c.acqf.as_str() {
                "LogConstrainedExpectedImprovement" => Box::new(
                    LogConstrainedExpectedImprovement::new(
                        model.clone(),
                        c.best_f,
                        c.objective_index,
                        c.constraints.clone(),
                        c.maximize,
                    )
                    .unwrap(),
                ),
                "ConstrainedExpectedImprovement" => Box::new(
                    ConstrainedExpectedImprovement::new(
                        model.clone(),
                        c.best_f,
                        c.objective_index,
                        c.constraints.clone(),
                        c.maximize,
                    )
                    .unwrap(),
                ),
                other => panic!("unknown acquisition function {other}"),
            };
            let label = format!(
                "{} obj={} cons={:?} max={}",
                c.acqf, c.objective_index, c.constraints, c.maximize
            );
            let many = acqf.forward_many(&xs).unwrap();
            let (mut verr, mut gerr) = (0.0f64, 0.0f64);
            for (i, x) in xs.iter().enumerate() {
                let (v, g) = acqf.forward_with_grad(x).unwrap();
                assert_eq!(many[i], acqf.forward(x).unwrap());
                let e = c.values[i];
                verr = verr.max(if acqf.is_log() {
                    log_err(v, e)
                } else {
                    scalar_rel(v, e)
                });
                gerr = gerr.max(rel_err(g.as_slice(), &c.grads[i]));
                if acqf.is_log() {
                    assert!(scalar_rel(many[i], v) <= 1e-14 * v.abs().max(1.0));
                }
            }
            r.check(&f.name, &format!("{label} value"), verr, RTOL);
            r.check(&f.name, &format!("{label} grad"), gerr, RTOL);
        }
    }
    assert!(n_cases >= 20, "too few constrained cases: {n_cases}");
    r.finish("constrained analytic expected improvement");
}
